// <process-2d> — 공정 4개(제선·제강·연주·열간압연) 설비 24개의 2D 동작 애니메이션.
// 장면 SVG와 단계 문장은 팀원의 '공정 동작 애니메이션' 페이지(공정_애니메이션.html)에서 그대로 가져왔고, 설비 id만 data_v2.js 기준으로 바꿨다.
//   속성   process="ironmaking|steelmaking|continuous_casting|rolling"  selected="<설비 id>"  theme="dark|light"
//   이벤트 process-select { process, id, name }  (bubbles, composed) — 공정·설비가 바뀔 때
//   메서드 setProcess(id), select(id) → boolean, play(), stop()
// 장면을 고칠 때는 SCENES의 SVG만 바꾸면 된다. data-s="1 2"는 그 단계 번호에서 강조되는 부분이다.

const PROCS = [ { "id": "ironmaking", "name": "제선", "items": [ { "id": "sinter_plant", "name": "소결기", "en": "Sinter Machine (DL식)", "steps": [ [ "분광 + 석회석 + 코크스 분 + 반광을 드럼 믹서에서 물과 섞어 작은 알갱이(의사 입자)로 만든다", "~5분" ], [ "이동하는 팔레트 대차 위에 상부광을 얇게 깔고 그 위에 배합 원료를 50~60cm 두께로 평평하게 장입한다", "" ], [ "점화로 아래를 지나며 가스 버너가 표층만 1,100~1,200°C로 점화한다", "~1분" ], [ "대차 아래 윈드박스가 공기를 아래로 빨아들여 불이 위에서 아래로 내려가며 탄다. 기계 길이 60~90m를 20분쯤 이동하는 동안 층 전체가 구워진다", "~20분" ], [ "끝단 배광부에서 소결 케이크가 덩어리째 떨어지고 크러셔가 깨뜨린다", "" ], [ "환형 쿨러에서 공기로 식힌다 (여기서 열 회수)", "~30분" ], [ "체질해서 5~50mm 성품은 고로로, 가루(반광)는 1번으로 되돌린다", "" ] ] }, { "id": "coke_oven", "name": "코크스 오븐", "en": "Coke Oven Battery", "steps": [ [ "상부 레일의 장입차가 장입구 뚜껑을 열고 분쇄 석탄 약 30t을 폭 45cm·높이 6~7m·길이 15m의 좁은 탄화실에 쏟아 넣는다", "~5분" ], [ "뚜껑을 닫고 레벨러 봉이 윗면을 평평하게 민다. 방은 완전히 밀폐되어 산소가 없다", "" ], [ "양쪽 벽(연소실)에서 가스를 태워 1,100~1,300°C로 벽을 통해 간접 가열. 석탄이 녹았다 굳으며 코크스가 된다. 발생 가스는 천장 상승관→집기관으로 빠져나가 회수(COG)", "18~24시간" ], [ "탄화 완료. 도어 머신이 압출기 쪽 문과 반대쪽(코크스 쪽) 문을 떼어낸다 (문 하나 무게 수 톤)", "~2분" ], [ "압출기 램이 전진해 빨갛게 달아오른 코크스 덩어리(약 1,000°C)를 통째로 밀어낸다 → 코크스 가이드를 지나 소화차로 떨어진다", "~30초" ], [ "전기기관차가 소화차를 소화탑 아래로 끌고 가 물을 뿌려 끈다 (CDQ면 질소로 천천히 식히고 증기 터빈 발전)", "~2분" ], [ "식은 코크스를 와프(경사면)에 쏟고 파쇄·체질해 고로로 보낸다", "" ] ] }, { "id": "blast_furnace", "name": "고로 · 벨리스 톱 장입 장치", "en": "Blast Furnace & Bell-less Top", "steps": [ [ "소결광·펠릿·괴광과 코크스를 각각 저장조에서 계량해 벨트 컨베이어로 노 꼭대기(노정, 높이 70~100m)까지 올린다", "" ], [ "벨리스 톱: 상부 호퍼 → 실 밸브를 닫고 하부 호퍼를 노 내부 압력(2~4기압)에 맞춰 가압 → 아래 밸브 열림", "" ], [ "회전 슈트가 각도를 바꿔가며 돌아 원료를 원형으로 고르게 깐다. 광석층 / 코크스층을 번갈아 쌓는다 (샌드위치 구조)", "1회 ~3분" ], [ "장입물은 6~8시간에 걸쳐 천천히 아래로 내려가고, 아래에서 올라오는 뜨거운 CO 가스와 반대 방향으로 만나 환원된다 (윗부분 괴상대: 고체 상태로 가열되며 산소를 잃음)", "6~8시간" ], [ "중간 연화융착대(역 V자): 광석이 연화되고 녹기 시작한다. 코크스층만 가스 통로로 남는다", "" ], [ "적하대: 쇳물과 슬래그 방울이 코크스 덩어리 사이로 떨어진다. 중앙에는 코크스 더미(노심)가 서 있다", "" ], [ "노상(바닥)에 아래 쇳물(1,500°C), 위 슬래그가 비중차로 층을 이뤄 고인다 → 출선구로", "" ], [ "노정 가스(BFG, CO 20% 이상)는 상승관으로 빠져나가 집진 후 열풍로·발전 연료로 재사용", "" ] ] }, { "id": "hot_stove", "name": "열풍로 · 풍구", "en": "Hot Stove & Tuyere", "steps": [ [ "[연소 모드] 열풍로 안에서 고로가스를 태워 축열실의 체커벽돌(구멍 뚫린 벽돌 더미)을 1,300°C까지 달군다. 연소 가스는 굴뚝으로", "~60분" ], [ "[송풍 모드] 밸브를 바꿔 송풍기의 찬 공기(약 150°C)를 반대 방향으로 벽돌 사이로 밀어 넣으면 1,100~1,250°C 열풍이 나온다", "~30분" ], [ "열풍로 3~4기가 교대: 1기가 송풍하는 동안 나머지가 연소(축열) → 고로에는 끊김 없이 열풍 공급", "" ], [ "열풍 본관 → 고로 하부를 둘러싼 환상관(도넛 배관) → 각 송풍지관 → 풍구로 분배", "" ], [ "풍구(구리, 물로 냉각)에서 열풍이 노 안으로 분사. 풍구 바로 앞 '레이스웨이'에서 코크스가 2,000°C 이상으로 타며 환원 가스(CO)와 열을 만든다. 미분탄도 같이 불어 넣음(PCI)", "" ], [ "풍구마다 관찰창(핍사이트)으로 레이스웨이 상태를 보고, 냉각수 온도로 풍구 손상 감시", "" ] ] }, { "id": "taphole_casthouse", "name": "출선구 · 주상", "en": "Tap Hole & Cast House", "steps": [ [ "출선구는 평소 머드(내화 점토)로 막혀 있다. 대형 고로는 출선구가 2~4개라 번갈아 거의 연속 출선", "" ], [ "개공기(드릴 기계)가 선회해 출선구 머드를 뚫는다", "~5분" ], [ "쇳물(1,500°C)이 먼저 쏟아지고 이어 슬래그가 섞여 나와 대탕도를 따라 흐른다", "출선 1회 1~2시간" ], [ "대탕도 끝 스키머(댐): 무거운 쇳물은 댐 아래로 통과, 가벼운 슬래그는 위로 넘쳐 다른 탕도로 흘러 둘이 분리된다", "" ], [ "쇳물은 용선 탕도 → 경동 탕도(좌우로 기울여 토페도카 바꿔가며 받음) → 아래 토페도카로", "" ], [ "슬래그는 슬래그 탕도 → 물로 급랭(수재, 모래알 같은 시멘트 원료) 또는 드라이핏에 부어 식힘", "" ], [ "출선 끝나면 머드건이 선회해 머드를 밀어 넣어 출선구를 다시 막는다", "" ], [ "주상 전체는 집진 후드로 덮여 연기·흄을 빨아들인다", "" ] ] }, { "id": "torpedo_car", "name": "토페도카", "en": "Torpedo Ladle Car", "steps": [ [ "주상 아래 레일에 빈 토페도카가 대기. 경동 탕도 끝 바로 아래에 상부 수선구가 오도록 위치", "" ], [ "쇳물을 받는다 (1대에 200~300t, 출선 1회로 여러 대 교대로 채움)", "~30분/대" ], [ "기관차가 제강 공장까지 수 km 이동. 어뢰 모양 본체와 두꺼운 내화물로 몇 시간 보온할 수 있다 (이 안에서 탈황을 하기도 함)", "~20~40분" ], [ "제강 장입장에서 본체를 회전(경동)시켜 수선구로 쇳물을 쏟아 장입 래들로 옮긴다", "~10분" ], [ "빈 차로 회송. 주기적으로 내부 슬래그 제거·내화물 보수", "" ] ] } ] }, { "id": "steelmaking", "name": "제강", "items": [ { "id": "hot_metal_pretreatment", "name": "용선 예비처리 (KR 탈황)", "en": "Hot Metal Pretreatment", "steps": [ [ "토페도카에서 받은 쇳물이 든 장입 래들을 KR 스테이션 아래로 이동", "" ], [ "위에서 내화물로 덮인 십자형 임펠러를 쇳물 속으로 내려 회전시킨다 → 소용돌이 발생", "~10분" ], [ "상부 호퍼에서 생석회계 탈황제를 뿌리면 소용돌이에 섞여 황(S)과 반응해 슬래그로 떠오른다", "" ], [ "임펠러를 올리고, 스키머(긁개)가 표면 슬래그를 긁어 슬래그 포트로 떨어뜨린다", "~10분" ], [ "(필요 시) 탈인·탈규: 산소나 산화철을 불어 넣어 인(P)·규소(Si)도 미리 뺀다", "" ] ] }, { "id": "bof_converter", "name": "전로 (BOF)", "en": "Basic Oxygen Furnace", "steps": [ [ "전로를 장입 쪽으로 기울이고(약 60°) 고철 슈트가 고철 15~25%를 쏟아 넣는다", "~2분" ], [ "크레인이 장입 래들을 들어 쇳물을 전로 입구로 붓는다", "~3분" ], [ "전로를 수직으로 세우고 후드(스커트)를 내려 입구를 덮는다", "" ], [ "산소 랜스가 위에서 내려와 노 바닥에서 1~2m 높이에서 초음속 산소를 분사 시작. 동시에 상부 호퍼에서 생석회·돌로마이트 투입", "취련 15~20분" ], [ "탄소가 산소와 반응해(C+O→CO) 격렬히 끓는다. 온도가 1,300 → 1,650~1,700°C로 올라간다. 슬래그가 거품처럼 부풀어 오르고(슬로핑 주의), 바닥 노즐에서 아르곤·질소를 불어 넣어 교반한다", "" ], [ "서브랜스를 꽂아 온도·탄소를 측정 → 목표에 맞으면 산소 중단, 랜스 상승", "" ], [ "전로를 반대쪽(출강 쪽)으로 기울여 옆구리 출강구로 용강을 아래 래들에 쏟는다. 이때 합금철·탈산제를 래들에 투입", "4~8분" ], [ "끝날 즈음 슬래그 다트를 출강구에 던져 넣어 슬래그가 함께 흘러나오는 것을 막는다", "" ], [ "다시 장입 쪽으로 기울여 남은 슬래그를 슬래그 포트로 배출한다", "" ], [ "질소를 세게 불어 남은 슬래그를 노벽에 발라 보호(슬래그 스플래싱) → 다음 회차. 1회차 전체 약 35~45분", "" ] ] }, { "id": "oxygen_lance_offgas", "name": "산소 랜스 · 배가스 후드/정화", "en": "Oxygen Lance & Off-gas (OG) System", "steps": [ [ "랜스는 길이 20m 이상의 3중 수냉 파이프. 끝단에 라발 노즐 4~6개가 비스듬히 뚫려 있다", "" ], [ "랜스 카가 랜스를 내려 노 바닥에서 1~2m 높이로 유지 (높이 올리면 소프트 블로우=슬래그 형성, 내리면 하드 블로우=탈탄)", "" ], [ "초음속(마하 2) 산소 제트가 쇳물 표면에 움푹한 구멍(캐비티)을 만들며 탄소·규소·인을 태운다. 산소 유량 200~300 m³/min", "" ], [ "동시에 입구 위 스커트가 내려와 밀착. 발생하는 CO 가스(1,600°C)를 공기 없이 그대로 빨아올린다(비연소 OG 방식)", "" ], [ "수냉 후드 → 스프레이 쿨러(물로 급랭) → 벤츄리 스크러버(먼지 제거) → IDF 송풍기", "" ], [ "CO 농도가 높은 구간은 가스 홀더에 저장해 연료로 재사용(LDG), 낮은 구간은 플레어 스택에서 태운다", "" ] ] }, { "id": "tapping_ladle_crane", "name": "출강 래들 · 크레인", "en": "Teeming Ladle & Ladle Crane", "steps": [ [ "빈 래들(100~300t, 내화벽돌 내장)이 래들 대차에 실려 전로 아래 출강 위치로 들어온다", "" ], [ "출강 시작과 함께 합금 슈트로 합금철·탈산제(Al 등)를 래들에 투입. 바닥 포러스 플러그에서 아르곤 기포를 올려 섞는다", "4~8분" ], [ "출강 끝 → 래들 위에 보온재를 뿌리고 대차가 빠져나온다", "" ], [ "천장 래들 크레인이 래들 양옆 트러니언 고리를 걸어 들어 올린다", "" ], [ "공장 길이 방향으로 이동해 LF·RH 처리 위치 또는 연주 터릿에 내려놓는다", "~5분" ], [ "래들 바닥 슬라이딩 게이트(밸브)는 닫힌 상태 유지. 연주에서 열림", "" ] ] }, { "id": "secondary_refining", "name": "2차 정련 (LF · RH)", "en": "Ladle Furnace & RH Degasser", "steps": [ [ "[LF] 래들을 LF 위치에 두고 수냉 루프(뚜껑)를 덮는다. 흑연 전극 3본이 내려와 아크 발생 → 용강을 분당 3~5°C로 가열", "~30분" ], [ "[LF] 바닥 아르곤으로 교반하며 합금 벌크·와이어 투입, 탈황 슬래그 조성. 온도·성분 샘플 채취 후 목표 도달", "" ], [ "[RH] 진공조(아래에 다리 2개=스노클) 를 내려 두 다리를 용강에 담근다", "" ], [ "[RH] 스팀 이젝터로 조 안을 진공(수십 Pa)으로 → 대기압 차이로 용강이 다리 속으로 1.4m 가량 빨려 올라간다", "" ], [ "[RH] 한쪽 다리(상승관)에 아르곤을 불어 넣으면 가벼워져 올라가고 반대 다리로 내려와 → 용강이 조와 래들 사이를 순환한다", "15~25분" ], [ "[RH] 진공 속에서 수소·질소·탄소가 빠지고 상부 호퍼로 합금 투입. 끝나면 진공을 풀고 조를 올린다", "" ] ] }, { "id": "ladle_transfer", "name": "래들 이송 → 연주", "en": "Ladle Transfer to Caster", "steps": [ [ "정련 끝난 래들에 보온 커버를 덮고 온도 측정 (연주 목표 온도까지 남은 시간 계산)", "" ], [ "래들 대차 또는 크레인으로 연주 설비까지 이동 (같은 공장 안, 수십~수백 m)", "~5~10분" ], [ "크레인이 래들 터릿의 빈 팔에 래들을 내려놓는다 → 연주 1단계로 이어짐", "" ], [ "바닥 슬라이딩 게이트 점검, 롱 노즐(쉬라우드) 장착 준비", "" ] ] } ] }, { "id": "continuous_casting", "name": "연주", "items": [ { "id": "ladle_turret", "name": "래들 · 래들 터릿", "en": "Ladle Turret", "steps": [ [ "크레인이 가득 찬 래들을 터릿의 비어 있는 팔(대기 위치)에 내려놓는다", "" ], [ "터릿이 180° 회전 → 새 래들이 턴디시 바로 위(주조 위치)로, 다 쓴 래들은 대기 위치로", "~1분" ], [ "래들 바닥 슬라이딩 게이트를 열고 롱 노즐을 밀착 → 용강이 공기와 닿지 않게 턴디시로 흘러 들어감 (아르곤 실링)", "" ], [ "래들 1개 약 40~60분이면 비워짐. 그 전에 다음 래들을 대기 팔에 올려둔다 → 끊기지 않고 연연주(시퀀스 캐스팅) 수십 회 연속", "40~60분/래들" ], [ "빈 래들은 크레인이 걷어가 슬래그 비우고 보수 후 전로로 되돌아감", "" ] ] }, { "id": "tundish", "name": "턴디시", "en": "Tundish", "steps": [ [ "턴디시 카가 예열(1,000°C 이상)된 턴디시를 주형 위로 가져와 위치시킨다", "" ], [ "롱 노즐로 용강이 들어온다. 내부 댐·위어가 흐름을 느리게 돌려 개재물(불순물)이 떠오르게 하고, 표면은 보온 플럭스로 덮는다", "" ], [ "액면 높이 500~700mm를 유지 (와전류 레벨 센서 피드백). 래들 교체 중에도 이 양으로 1~2분 동안 주조를 이어 간다", "" ], [ "바닥 출구마다 스토퍼 로드(또는 슬라이딩 게이트)가 상하로 움직여 침지 노즐(SEN)로 나가는 양을 조절 → 각 주형(스트랜드)으로", "" ], [ "주형 쪽 액면 센서 신호에 따라 스토퍼가 수 mm 단위로 계속 미세 조정된다", "" ] ] }, { "id": "cc_mold", "name": "주형(몰드) · 몰드 진동 장치", "en": "Mold & Oscillator", "steps": [ [ "[주조 시작] 더미 바(쇠 마개가 달린 긴 사슬)를 아래에서 밀어 올려 주형 바닥을 막는다", "" ], [ "침지 노즐이 액면 아래로 용강을 넣는다. 액면 위엔 몰드 파우더를 뿌려 보온·윤활·산화 방지", "" ], [ "수냉 구리판(길이 약 900mm, 물이 초속 수 m로 흐름)에 닿은 면이 10~20mm 두께의 응고 껍질(셸)이 된다. 속은 아직 액체", "" ], [ "몰드 전체가 상하로 ±3~6mm, 초당 수 회 진동 → 내려가는 속도보다 잠깐 빨리 내려가는 순간(네거티브 스트립)에 껍질이 벽에서 떨어져 달라붙지 않는다. 표면에 가로 줄(오실레이션 마크)이 남는 이유", "" ], [ "액면은 ±3mm 이내로 제어(스토퍼와 연동). 열전대 수십 개가 벽 온도를 감시해 껍질 터짐(브레이크아웃) 징후를 잡는다", "" ], [ "껍질이 충분해지면 더미 바가 아래로 끌려 내려가며 가닥이 주형을 빠져나간다 → 이후 연속", "" ] ] }, { "id": "secondary_cooling", "name": "2차 냉각 · 가이드 롤", "en": "Secondary Cooling & Segment Rolls", "steps": [ [ "주형을 나온 가닥(껍질 두께 1~2cm, 속은 액체 1,500°C)이 바로 풋 롤에 지지된다", "" ], [ "위아래 롤 쌍(세그먼트) 수십 조가 가닥을 양쪽에서 붙잡아 부풀지 않게 하고, 수직 → 반지름 9~12m 곡선 → 수평으로 안내한다", "" ], [ "롤과 롤 사이에서 물(또는 물+공기 미스트)을 뿌려 표면을 800~1,000°C로 식힌다. 구간별로 세기를 다르게(위쪽 세게, 아래쪽 약하게)", "" ], [ "응고가 바깥에서 안쪽으로 진행. 액체 심(liquid core)이 뾰족하게 좁아지며 주형에서 10~30m 떨어진 곳에서 완전히 굳는다 (주속 1~2 m/min 기준)", "10~20분" ], [ "완전 응고 직전 구간에서 롤 간격을 조금 좁혀 누르면(경압하) 가운데 성분 쏠림(중심 편석)이 줄어든다", "" ] ] }, { "id": "withdrawal_straightener", "name": "인발 · 교정 롤", "en": "Withdrawal & Straightening", "steps": [ [ "세그먼트 중 일부 롤은 모터 구동(핀치 롤)이라 가닥을 일정 속도로 끌어내린다. 이 속도가 주조 속도(슬라브 1~2 m/min)", "" ], [ "곡선 끝에서 수평으로 바뀌는 구간(언벤딩)에서 여러 롤이 가닥을 조금씩 편다. 속이 아직 덜 굳은 상태라 천천히, 여러 점에서", "" ], [ "주조 시작 때는 더미 바가 가닥 머리를 끌고 수평부까지 나온 뒤 분리되어 위로 회수", "" ], [ "주조 속도는 주형 액면·온도·터릿 교체 상황에 맞춰 수시로 바뀜 (래들 교체 중엔 감속)", "" ] ] }, { "id": "torch_cutter", "name": "절단기 · 배출 롤러", "en": "Torch Cutting & Run-out", "steps": [ [ "토치 절단기(TCM)가 가닥을 물고 가닥과 같은 속도로 함께 움직이기 시작 (멈춰 있으면 움직이는 가닥을 자를 수 없음)", "" ], [ "산소-가스 토치가 가닥 폭 방향으로 가로질러 이동하며 녹여 자른다. 슬라브 길이 5~12m, 두께 25cm 자르는 데 수 분", "2~4분" ], [ "절단 완료 → 절단기는 시작 위치로 복귀, 잘린 슬라브는 롤러 테이블로 앞서 나간다", "" ], [ "아랫면 절단 찌꺼기(버)를 디버러가 긁어내고, 마킹기가 번호를 찍는다", "" ], [ "롤러 테이블 → 크레인/대차로 슬라브 야드에 쌓아 식히거나(900°C → 상온), 뜨거운 채로 바로 압연 재가열로로 직송(HCR, 에너지 절약)", "" ] ] } ] }, { "id": "rolling", "name": "열간압연", "items": [ { "id": "reheating_furnace", "name": "재가열로", "en": "Reheating Furnace (워킹빔식)", "steps": [ [ "장입 롤러 테이블이 슬라브(상온 또는 열간 직송 700~900°C)를 장입 도어 앞까지 보내고, 도어가 열리면 안으로 밀어 넣는다", "" ], [ "워킹빔이 '올리고 → 앞으로 → 내리고 → 뒤로' 사각형 운동을 반복해 슬라브를 한 칸씩 전진 (슬라브 수십 장이 줄지어 있음)", "1스텝 ~1분" ], [ "예열대(배기 열로 데움) → 가열대(상·하부 버너, 가스 연소) → 균열대(속까지 온도 균일) 순으로 통과하며 1,200~1,250°C로", "2~3시간" ], [ "표면이 공기와 닿아 1~3mm 산화철 껍질(스케일)이 생긴다 → 다음 설비에서 제거", "" ], [ "추출기가 추출 도어로 슬라브를 꺼내 롤러 테이블에 올린다. 색: 검정 → 암적색 → 주황 → 밝은 노랑", "" ] ] }, { "id": "descaler", "name": "고압수 스케일 제거기", "en": "Hydraulic Descaler", "steps": [ [ "추출 직후 슬라브가 디스케일링 박스(터널)를 통과", "" ], [ "위아래 헤더의 평판 노즐 수십 개가 150~200 bar 고압수를 비스듬히 분사", "" ], [ "급랭 수축 + 물의 충격으로 스케일이 판 모양으로 깨져 날아간다", "수 초" ], [ "벗겨진 스케일은 아래 수로로 씻겨 내려가고, 슬라브 표면 온도는 잠깐 수십 °C 떨어짐", "" ], [ "조압연 입측·사상압연 입측에도 2차 디스케일러가 있어 다시 생긴 얇은 스케일을 또 제거", "" ] ] }, { "id": "roughing_mill", "name": "조압연기", "en": "Roughing Mill (4-High Reversing)", "steps": [ [ "(폭 조정) 에저의 수직 롤 한 쌍이 슬라브 옆면을 눌러 폭을 맞춘다", "" ], [ "4단 압연기(위아래 작업롤 Ø~1,000mm + 그 바깥 백업롤)에 슬라브가 들어가 한 번 눌린다 → 두께 감소, 길이 증가", "" ], [ "롤 회전을 반대로 돌려 슬라브를 다시 되돌려 보내며 또 누른다 (리버싱). 패스마다 압하 장치가 롤 간격을 더 좁힌다", "1패스 ~10초" ], [ "5~7회 왕복해 두께 250mm → 30~40mm, 길이 10m → 40~90m 의 '트랜스퍼 바'가 된다 (온도 1,100°C 전후)", "~2분" ], [ "트랜스퍼 바가 긴 롤러 테이블(또는 코일 박스)을 지나 사상압연기로. 앞뒤 끝은 크롭 시어로 잘라냄", "" ] ] }, { "id": "finishing_mill", "name": "사상압연기", "en": "Finishing Mill (F1~F7 Tandem)", "steps": [ [ "크롭 시어가 트랜스퍼 바 머리·꼬리(모양 불량)를 잘라내고, 사상 디스케일러가 표면 스케일 제거", "" ], [ "F1~F7 스탠드 7기를 '연속으로' 통과. 각 스탠드는 4단(작업롤 Ø600~800 상하 + 백업롤 Ø1,400~1,600 상하). 한 스탠드씩 두께가 30~50%씩 줄어듦", "판 1장 통과 ~1~2분" ], [ "얇아질수록 길어지므로 뒤 스탠드일수록 롤이 빨리 돈다 (F1 수 m/s → F7 최대 20 m/s). 스탠드 사이 루퍼 팔이 판을 들어 올려 장력을 일정하게 유지", "" ], [ "자동 두께 제어(AGC)가 유압 실린더로 롤 간격을 ms 단위로 보정. 롤 벤딩·시프팅으로 판 가운데가 두꺼워지는 크라운·형상(물결)을 잡는다", "" ], [ "작업롤에 냉각수를 계속 뿌려 열 변형·마모를 억제. 마모가 쌓이면 수 시간마다 롤 교체", "" ], [ "출측에서 두께(X선)·폭·평탄도·온도(FDT 850~900°C) 측정. 최종 두께 1.2~25mm, 폭 700~1,600mm", "~1,000 m/min" ] ] }, { "id": "runout_table", "name": "런아웃 테이블 · 냉각 설비", "en": "Run-out Table & Laminar Cooling", "steps": [ [ "사상압연 출측에서 850~900°C 띠강이 롤러 테이블 위를 초속 10~20m로 이동한다", "" ], [ "상부 U자 관 헤더 수십 개에서 물이 커튼처럼 떨어지고(라미나 플로우), 하부에서 스프레이가 올라와 위아래 동시에 식힌다", "" ], [ "구간(밴크)별로 물을 켜고 끄는 패턴으로 냉각 속도를 조절: 앞쪽 집중(전단 냉각), 뒤쪽 집중(후단 냉각), 중간 쉬었다 다시(간헐 냉각)", "통과 ~10~20초" ], [ "권취 온도(CT) 500~700°C에 맞춰 조직이 결정됨: 천천히 식히면 부드러운 페라이트, 빨리 식히면 단단한 베이나이트 등", "" ], [ "측면 사이드 가이드가 띠가 비뚤어지지 않게 잡으며 권취기 입구로 보낸다", "" ] ] }, { "id": "coiler", "name": "권취기", "en": "Down Coiler", "steps": [ [ "띠 선단이 핀치 롤 사이로 들어가면 롤이 선단을 아래로 꺾어 맨드릴 쪽으로 보낸다", "" ], [ "맨드릴을 둘러싼 래퍼 롤 3~4개가 선단을 맨드릴에 밀어붙여 두세 바퀴 감기게 한다", "~2초" ], [ "감기면 래퍼 롤이 물러나고 맨드릴이 띠 속도에 맞춰 회전하며 장력을 걸어 단단하게 감는다. 코일 지름이 점점 커진다 (최대 Ø2m, 20~30t)", "~1~2분" ], [ "꼬리까지 감기면 맨드릴이 수축(지름 작아짐)하고 코일 카가 아래에서 받쳐 코일을 빼낸다", "" ], [ "결속기가 띠로 묶고 번호를 마킹 → 코일 야드로. 권취기는 2~3대가 번갈아 받아 연속 생산", "" ], [ "완성품 열연코일: 두께 1.2~25mm, 폭 700~1,600mm. 이후 냉연·도금 또는 그대로 출하", "" ] ] } ] } ];

