    this.$('svgwrap').innerHTML = `<svg class="svg hl" viewBox="0 0 600 320" xmlns="http://www.w3.org/2000/svg">${SCENES[d.id] || '<text x="300" y="160" class="lbl">장면 준비 중</text>'}</svg>`;
