      b.onclick = () => { this.hidePeek(); this.ei = +b.dataset.i; this.sub = 0; this.render(); this.emit(); };
      b.onmouseenter = b.onfocus = () => this.showPeek(b); b.onmouseleave = b.onblur = () => this.hidePeek();
